class CountingList extends ArrayList<String> {
    int added = 0;

    @Override
    public boolean add(String item) {
        added++;
        return super.add(item);
    }
}

var list = new CountingList();
list.addAll(List.of("a", "b", "c"));
list.add("d");
System.out.println(list.added);
